// ─── File: src/main/java/com/bank/grpc/server/TransferServiceImpl.java ───
package com.bank.grpc.server;

import com.bank.grpc.gen.*;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

// The gRPC server. Methods map 1:1 to the rpc methods in the .proto contract.
@GrpcService
public class TransferServiceImpl extends TransferServiceGrpc.TransferServiceImplBase {

    private static final Logger log = LoggerFactory.getLogger(TransferServiceImpl.class);

    // Unary call: one request → one reply.
    @Override
    public void transfer(TransferRequest request, StreamObserver<TransferReply> responseObserver) {
        log.info("gRPC transfer {} paise from {} to {}",
                request.getAmountPaise(), request.getFrom(), request.getTo());
        TransferReply reply = TransferReply.newBuilder()
                .setTransferId("TXF-001")
                .setStatus("COMPLETED")
                .build();
        responseObserver.onNext(reply);     // send the single reply
        responseObserver.onCompleted();     // close the call
    }

    // Server streaming: emit a sequence of risk signals, then complete.
    @Override
    public void streamRiskSignals(TransferRequest request,
                                  StreamObserver<RiskSignal> responseObserver) {
        responseObserver.onNext(RiskSignal.newBuilder().setCode("VELOCITY").setScore(10).build());
        responseObserver.onNext(RiskSignal.newBuilder().setCode("GEO").setScore(5).build());
        responseObserver.onNext(RiskSignal.newBuilder().setCode("AMOUNT").setScore(20).build());
        responseObserver.onCompleted();
    }
}
```

```java
// ─── File: src/main/java/com/bank/grpc/client/TransferClient.java ───
package com.bank.grpc.client;

import com.bank.grpc.gen.*;
import io.grpc.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.Iterator;

// A client service calling the gRPC transfer service. The remote call looks
// like a local method thanks to the generated stub.
public class TransferClient {

    private static final Logger log = LoggerFactory.getLogger(TransferClient.class);

    public static void main(String[] args) {
        // HTTP/2 channel, reused for many multiplexed calls.
        ManagedChannel channel = ManagedChannelBuilder
                .forAddress("localhost", 9090).usePlaintext().build();

        TransferServiceGrpc.TransferServiceBlockingStub stub =
                TransferServiceGrpc.newBlockingStub(channel);

        TransferRequest request = TransferRequest.newBuilder()
                .setFrom("SAV2001").setTo("CUR3001").setAmountPaise(5000000).build();

        // Unary call.
        TransferReply reply = stub.transfer(request);
        log.info("Reply: {} -> {}", reply.getTransferId(), reply.getStatus());

        // Server-streaming call: iterate risk signals as they arrive.
        Iterator<RiskSignal> signals = stub.streamRiskSignals(request);
        int total = 0;
        while (signals.hasNext()) {
            RiskSignal s = signals.next();
            total += s.getScore();
            log.info("Risk signal {} score {}", s.getCode(), s.getScore());
        }
        log.info("Total risk score: {}", total);

        channel.shutdown();
    }
}
```
